mapper.select:
SELECT

FROM audit_evidence e


    e.deleted = 0

        AND e.project_id = #{q.projectId}


        AND e.issue_id = #{q.issueId}


        AND e.status = #{q.status}


        AND e.evidence_type = #{q.evidenceType}


        AND e.reliability = #{q.reliability}


        AND (e.evidence_name LIKE CONCAT('%', #{q.keyword}, '%')
             OR e.evidence_no LIKE CONCAT('%', #{q.keyword}, '%'))


        AND e.submit_by = #{currentUserId}


        AND e.status = 1
        AND e.submit_by <> #{currentUserId}


ORDER BY


        e.submit_time ASC


        e.update_time DESC

SELECT CAST(status AS CHAR) AS `key`, COUNT(1) AS `value` FROM audit_evidence WHERE deleted = 0
AND project_id = #{projectId}
GROUP BY status ORDER BY status

SELECT evidence_type AS `key`, COUNT(1) AS `value` FROM audit_evidence WHERE deleted = 0
AND project_id = #{projectId}
GROUP BY evidence_type ORDER BY COUNT(1) DESC
